def test_admin_read_cancellation_survives_failing_handle_close(tmp_path,monkeypatch,revision):
    from subfleet import retention_git as current
    if revision=='head': m=current
    else:
        import subprocess
        name='subfleet._r4_git_release';m=types.ModuleType(name);m.__package__='subfleet';sys.modules[name]=m
        source=subprocess.run(['git','show','a093fb4b6:subfleet/retention_git.py'],check=True,capture_output=True,text=True).stdout
        exec(compile(source,'<retention_git release>','exec'),m.__dict__)
    admin=tmp_path/'admin';admin.mkdir();(admin/'ref').write_bytes(b'1'*40)
    original_open,original_close=os.open,os.close;handles=[];attempted=[]
    primary=KeyboardInterrupt('read');secondary=OSError(errno.EIO,'handle close');caught=None
    def open_(name,*a,**kw):
        fd=original_open(name,*a,**kw)
        if name=='ref':handles.append(fd)
        return fd
    def read(fd,n):
        if fd in handles:raise primary
        raise AssertionError('unexpected read')
    def close(fd):
        attempted.append(fd);original_close(fd)
        if fd in handles:raise secondary
    with monkeypatch.context() as patch:
        patch.setattr(os,'open',open_);patch.setattr(os,'read',read);patch.setattr(os,'close',close)
        try:m.admin_objects(admin,'sha1')
        except BaseException as exc:caught=exc
    evidence('admin-'+revision,result=type(caught).__name__,original_survived=caught is primary,secondary_survived=caught is secondary,context_is_primary=caught.__context__ is primary,attempted=attempted)
    assert caught is primary

