@pytest.mark.xfail(strict=True,reason='Listed difference L4: second asynchronous interrupt between drain closes aborts cleanup')
def test_repeated_interrupt_between_cleanup_attempts(tmp_path,monkeypatch):
    original_close=os.close;fds=[os.open(tmp_path/'owned',os.O_RDWR|os.O_CREAT,0o600) for _ in range(3)]
    primary=KeyboardInterrupt('body');secondary=KeyboardInterrupt('second interrupt');attempted=[]
    offset=next(i.offset for i in dis.get_instructions(rfs._close_all) if i.opname=='FOR_ITER')
    tool=sys.monitoring.DEBUGGER_ID;fired=[];caught=None
    def instruction(code,at):
        if code is rfs._close_all.__code__ and at==offset and len(attempted)==1:
            fired.append(at);raise secondary
    def close(fd):attempted.append(fd);original_close(fd)
    sys.monitoring.use_tool_id(tool,'r4 repeated interruption')
    try:
        sys.monitoring.register_callback(tool,sys.monitoring.events.INSTRUCTION,instruction)
        sys.monitoring.set_local_events(tool,rfs._close_all.__code__,sys.monitoring.events.INSTRUCTION)
        with monkeypatch.context() as patch:
            patch.setattr(os,'close',close)
            try:
                with rfs._cleanup(fds):raise primary
            except BaseException as exc:caught=exc
        evidence('repeated-drain',offset=offset,fired=fired,attempted=attempted,leaked=alive(fds),original_survived=caught is primary,secondary_survived=caught is secondary)
        assert caught is primary and not alive(fds)
    finally:
        sys.monitoring.set_local_events(tool,rfs._close_all.__code__,0)
        sys.monitoring.register_callback(tool,sys.monitoring.events.INSTRUCTION,None)
        sys.monitoring.free_tool_id(tool)
        for fd in alive(fds):original_close(fd)

