        def close(fd):attempted.append(fd);original_close(fd)
        def instruction(code,at):
            if code is base.walk.__code__ and at in offsets and len(attempted)==1:
                fired.append(at);raise secondary
        it=base.walk(root_fd);tool=sys.monitoring.DEBUGGER_ID;caught=None
